mapper.select:
SELECT 
FROM pos_sale s



        (s.sale_no LIKE CONCAT('%', #{q.keyword}, '%') OR m.phone = #{q.keyword} OR m.member_code = #{q.keyword})

    AND s.kind = #{q.kind}
    AND s.status = #{q.status}
    AND s.store_id = #{q.storeId}
    AND s.terminal_id = #{q.terminalId}
    AND s.create_by = #{q.cashierId}
    AND s.member_id = #{q.memberId}
    AND s.shift_id = #{q.shiftId}
    AND EXISTS (SELECT 1 FROM pos_sale_item i WHERE i.sale_id = s.id AND i.material_id = #{q.materialId})
    AND s.business_date >= #{q.begin}
    AND s.business_date <= #{q.end}

ORDER BY s.id DESC
